using Microsoft.Extensions.ML;
using TicketClassifier.Models;
using TicketClassifier.Services;

var builder = WebApplication.CreateBuilder(args);
builder.Services.AddControllers();

// Train the model at startup and register as singleton
var modelService = new TicketModelService(builder.Environment);
modelService.TrainAndEvaluate();
builder.Services.AddSingleton(modelService);

// Register pooled prediction engine (thread-safe)
builder.Services.AddPredictionEnginePool<TicketInput, TicketPrediction>()
    .FromFile(modelService.GetModelPath());

var app = builder.Build();
app.MapControllers();
app.Run();

