using Microsoft.ML;
using TicketClassifier.Models;

namespace TicketClassifier.Services;

public class TicketModelService
{
    private readonly MLContext _mlContext;
    private readonly string _dataPath;
    private readonly string _modelPath;
    private ModelMetrics? _metrics;
    private string[] _labelNames = [];

    public ModelMetrics? Metrics => _metrics;
    public string[] LabelNames => _labelNames;

    public TicketModelService(IWebHostEnvironment env)
    {
        _mlContext = new MLContext(seed: 42);
        _dataPath = Path.Combine(env.ContentRootPath, "Data", "tickets.csv");
        _modelPath = Path.Combine(env.ContentRootPath, "Data", "model.zip");
    }

    public void TrainAndEvaluate()
    {
        var data = _mlContext.Data.LoadFromTextFile<TicketInput>(
            _dataPath, hasHeader: true, separatorChar: ',', allowQuoting: true);

        var pipeline = _mlContext.Transforms.Text.FeaturizeText("SubjectFeaturized", nameof(TicketInput.Subject))
            .Append(_mlContext.Transforms.Text.FeaturizeText("DescriptionFeaturized", nameof(TicketInput.Description)))
            .Append(_mlContext.Transforms.Concatenate("Features", "SubjectFeaturized", "DescriptionFeaturized", nameof(TicketInput.Priority)))
            .Append(_mlContext.Transforms.Conversion.MapValueToKey("Label", nameof(TicketInput.Category)))
            .Append(_mlContext.MulticlassClassification.Trainers.SdcaMaximumEntropy("Label", "Features"))
            .Append(_mlContext.Transforms.Conversion.MapKeyToValue("PredictedLabel"));

        // Cross-validate for metrics (better for small datasets)
        var cvResults = _mlContext.MulticlassClassification.CrossValidate(data, pipeline, numberOfFolds: 3);
        var avgMicro = cvResults.Average(r => r.Metrics.MicroAccuracy);
        var avgMacro = cvResults.Average(r => r.Metrics.MacroAccuracy);
        var avgLogLoss = cvResults.Average(r => r.Metrics.LogLoss);
        var avgLogLossReduction = cvResults.Average(r => r.Metrics.LogLossReduction);

        _metrics = new ModelMetrics
        {
            MicroAccuracy = (float)avgMicro,
            MacroAccuracy = (float)avgMacro,
            LogLoss = (float)avgLogLoss,
            LogLossReduction = (float)avgLogLossReduction
        };

        // Train final model on all data
        var model = pipeline.Fit(data);

        // Extract label names in order from the key-value mapping
        var schema = model.Transform(data).Schema;
        var labelColumn = schema["Label"];
        var keyType = labelColumn.Type as Microsoft.ML.Data.KeyDataViewType;
        if (keyType != null)
        {
            var labelBuffer = new VBuffer<ReadOnlyMemory<char>>();
            labelColumn.GetKeyValues(ref labelBuffer);
            _labelNames = labelBuffer.DenseValues().Select(v => v.ToString()).ToArray();
        }

        _mlContext.Model.Save(model, data.Schema, _modelPath);
    }

    public string GetModelPath() => _modelPath;
}

